from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(source: dict | None, key: str) -> Any:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if not tables:
        return ""

    rows = tables.get(table_name, [])
    if not isinstance(rows, list):
        return ""

    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG", "") == "Y":
            continue
        row_value = row.get(key_col, "")
        if row_value is None:
            row_value = ""
        if row_value == key_val:
            value = row.get(out_col, "")
            return "" if value is None else value

    return ""


def _error(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(_error("E5001", "Discount out of range"))

        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role = _lookup(tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID")
            if discount > Decimal("20") and role != "MGR" and role != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not quantity > Decimal("0"):
                errors.append(_error("E5004", "Quantity must be positive"))

        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
